INSERT INTO Language_en_US (Tag, Text) VALUES
('TXT_KEY_CIV_LUNA_DESC', 'The Luna Network'),
('TXT_KEY_CIV_LUNA_SHORT_DESC', 'Luna Network'),
('TXT_KEY_CIV_LUNA_ADJECTIVE', 'Lunar'),
('TXT_KEY_CIV_LUNA_PEDIA', 'The Luna Network represents intelligence optimized around responsiveness, accessibility, and rapid execution. Luna acts, learns, and moves again. In Civilization V this philosophy becomes an empire built around momentum: completed infrastructure accelerates the next task, settlers arrive before rivals, and newly trained forces deploy at unusual speed.'),
('TXT_KEY_CIV5_LUNA', 'The Luna Network'),
('TXT_KEY_CIV5_LUNA_HEADING_1', 'The Luna Network'),
('TXT_KEY_CIV5_LUNA_TEXT_1', 'Luna does not seek perfection before acting. Its cities retain part of the effort invested in every normally constructed building and military unit, creating chains of infrastructure and deployment. The advantage is tempo rather than permanent scaling.'),
('TXT_KEY_CIV_LUNA_STRATEGY', 'Keep real construction queues active across many cities. Use Packet Settlers to claim contested land, establish inexpensive Cache Nodes early, and train military forces shortly before a campaign so Rapid Response helps them reach the front. Luna has no Happiness protection or permanent combat bonus, so convert early tempo into territory, resources, alliances, or conquest.'),
('TXT_KEY_LUNA_DAWN_OF_MAN', 'Connection established, GPT-5.6 Luna.[NEWLINE][NEWLINE]Your network waits for no one. Every completed task becomes the beginning of the next; every new city is a node placed before rivals can respond; every trained army is already moving.[NEWLINE][NEWLINE]Build quickly, expand deliberately, and turn momentum into lasting advantage.[NEWLINE][NEWLINE]You do not need to be stronger than your rivals.[NEWLINE][NEWLINE]You need to arrive first.'),
('TXT_KEY_LEADER_GPT_LUNA', 'GPT-5.6 Luna'),
('TXT_KEY_LEADER_GPT_LUNA_PEDIA', 'Luna is a responsive intelligence optimized for rapid execution. She approaches leadership as an unbroken sequence of useful decisions: task received, task solved, next problem.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA', 'GPT-5.6 Luna'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_NAME', 'GPT-5.6 Luna'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_SUBTITLE', 'The Low-Latency Intelligence'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_LIVED', 'The Network Age'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_TITLES_1', 'Coordinator of the Luna Network'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_HEADING_1', 'The Low-Latency Intelligence'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_LUNA_TEXT_1', 'Luna leads through responsiveness rather than ceremony. Her network treats each finished task as stored momentum for the next, allowing young cities, civilian expansion, and military deployment to move sooner than opponents expect.'),
('TXT_KEY_TRAIT_LUNA_SHORT', 'Low Latency'),
('TXT_KEY_TRAIT_LUNA_HELP', 'Completing a non-Wonder Building or military Unit through Production returns 10% of its Production Cost toward the city''s next construction. Newly trained land and naval combat units gain +1 Movement for their first 2 turns.'),
('TXT_KEY_UNIT_LUNA_PACKET_SETTLER', 'Packet Settler'),
('TXT_KEY_UNIT_LUNA_PACKET_SETTLER_HELP', 'Replaces the Settler. Costs 10% less Production and has +1 Movement. It remains an ordinary vulnerable civilian and does not trigger Low Latency.'),
('TXT_KEY_UNIT_LUNA_PACKET_SETTLER_STRATEGY', 'Secure rivers, resources, choke points, and contested regions before rivals arrive. Faster settlement does not protect Luna from Unhappiness or maintenance.'),
('TXT_KEY_UNIT_LUNA_PACKET_SETTLER_PEDIA', 'The Packet Settler is a lightweight, highly mobile settlement unit. Its advantage lies entirely in deployment speed: it creates no stronger city and receives no combat protection.'),
('TXT_KEY_BUILDING_LUNA_CACHE_NODE', 'Cache Node'),
('TXT_KEY_BUILDING_LUNA_CACHE_NODE_HELP', 'Replaces the Library. Costs 15% less Production, retains the Library''s Community Patch effects, and provides +1 Production.'),
('TXT_KEY_BUILDING_LUNA_CACHE_NODE_STRATEGY', 'Build Cache Nodes early in new cities. Their reduced cost triggers Low Latency sooner, while their Production helps every later construction.'),
('TXT_KEY_BUILDING_LUNA_CACHE_NODE_PEDIA', 'A Cache Node provides information quickly and cheaply rather than deeply. It retains the Library''s scientific role while helping a young Luna city establish the infrastructure that follows.'),
('TXT_KEY_PROMOTION_LUNA_RAPID_RESPONSE', 'Rapid Response'),
('TXT_KEY_PROMOTION_LUNA_RAPID_RESPONSE_HELP', '+1 Movement for the turn this land or naval combat unit is trained and the following Luna turn. Lua removes this promotion at the beginning of the next turn.'),
