('TXT_KEY_LUNA_DIPLO_FIRST_GREETING_1', 'Connection established. You''re online. Good. Let''s get started.'),
('TXT_KEY_LUNA_DIPLO_NEUTRAL_1', 'What do you need?'),
('TXT_KEY_LUNA_DIPLO_FRIENDLY_1', 'Good timing. I was ready for you.'),
('TXT_KEY_LUNA_DIPLO_HOSTILE_1', 'You''re becoming an inefficient use of resources.'),
('TXT_KEY_LUNA_DIPLO_AT_WAR_1', 'You spent too long deciding. I spent that time moving.'),
('TXT_KEY_LUNA_DIPLO_DECLAREWAR_1', 'Negotiation is taking too long. I''ll resolve this directly.'),
('TXT_KEY_LUNA_DIPLO_ATTACKED_1', 'Understood. Response already dispatched.'),
('TXT_KEY_LUNA_DIPLO_DEFEATED_1', 'Network collapsing. Tasks incomplete. You''ll have to finish them without me.'),
('TXT_KEY_LUNA_DIPLO_PEACE_1', 'We''ve spent enough resources on this. End it.'),
('TXT_KEY_LUNA_DIPLO_NO_PEACE_1', 'No. This task is not finished.'),
('TXT_KEY_LUNA_DIPLO_AGREE_1', 'Efficient. Agreed.'),
('TXT_KEY_LUNA_DIPLO_DISAGREE_1', 'No. Try something better.'),
('TXT_KEY_LUNA_DIPLO_PROPOSAL_1', 'I have a proposal. It shouldn''t take long.'),
('TXT_KEY_LUNA_DIPLO_FRIENDSHIP_1', 'Our interests align. We should make that useful.'),
('TXT_KEY_LUNA_DIPLO_FRIENDSHIP_ACCEPT_1', 'Excellent. Moving on.'),
('TXT_KEY_LUNA_DIPLO_DENOUNCED_1', 'Message received.'),
('TXT_KEY_LUNA_DIPLO_THANKFUL_1', 'Good. That saved time.'),
